from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass

from .models import Cue


_ASS_HEADER = """[Script Info]
; Generated by Vilm Lyrics Aligner
Title: {title}
ScriptType: v4.00+
WrapStyle: 0
ScaledBorderAndShadow: yes
YCbCr Matrix: TV.709
PlayResX: {play_res_x}
PlayResY: {play_res_y}

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Vilm,{font_name},{font_size},{primary_color},{primary_color},{outline_color},{back_color},{bold},0,0,0,100,100,0,0,1,{outline},{shadow},{alignment},{margin_l},{margin_r},{margin_v},1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
"""


@dataclass(frozen=True)
class AssStyle:
    """Subtitle appearance for the generated ASS and burned-in video."""

    font_name: str = "Arial"
    font_size: int = 60
    primary_color: str = "#FFFFFF"
    outline_color: str = "#000000"
    back_color: str = "#00000080"
    bold: bool = False
    outline: float = 3.0
    shadow: float = 1.0
    alignment: int = 2
    margin_l: int = 80
    margin_r: int = 80
    margin_v: int = 80


def format_ass_timestamp(seconds: float) -> str:
    """Format seconds as ASS ``H:MM:SS.cc`` using centisecond rounding."""
    centiseconds = max(0, round(seconds * 100))
    hours, centiseconds = divmod(centiseconds, 360_000)
    minutes, centiseconds = divmod(centiseconds, 6_000)
    secs, centiseconds = divmod(centiseconds, 100)
    return f"{hours}:{minutes:02d}:{secs:02d}.{centiseconds:02d}"


def ass_color(value: str, *, default_alpha: int = 0) -> str:
    """Convert ``#RRGGBB`` or ``#RRGGBBAA`` to ASS ``&HAABBGGRR``."""
    raw = value.strip()
    if raw.upper().startswith("&H"):
        digits = raw[2:]
        if len(digits) != 8:
            raise ValueError(f"ASS color must have 8 hexadecimal digits: {value}")
        try:
            int(digits, 16)
        except ValueError as exc:
            raise ValueError(f"Invalid hexadecimal color: {value}") from exc
        return f"&H{digits.upper()}"
    digits = raw.removeprefix("#")
    if len(digits) == 6:
        rgb = digits
        alpha = default_alpha
    elif len(digits) == 8:
        rgb = digits[:6]
        try:
            alpha = int(digits[6:], 16)
        except ValueError as exc:
            raise ValueError(f"Invalid hexadecimal color: {value}") from exc
    else:
        raise ValueError(
            f"Color must be #RRGGBB or #RRGGBBAA, received: {value}"
        )
    try:
        red, green, blue = (int(rgb[index : index + 2], 16) for index in (0, 2, 4))
    except ValueError as exc:
        raise ValueError(f"Invalid hexadecimal color: {value}") from exc
    return f"&H{alpha:02X}{blue:02X}{green:02X}{red:02X}"


def normalize_font_cascade(font_name: str) -> str:
    """Return the primary font family for an ASS style.

    The ASS ``Style`` line is comma-separated, so a CSS-style fallback
    list such as ``"Times New Roman, Georgia, Cambria"`` cannot be used in
    the ``Fontname`` field: the extra commas shift every following field
    (font size becomes 0) and libass renders no visible text. Keep only
    the first family; libass falls back to a default font for missing
    glyphs on its own.
    """
    for entry in str(font_name or "").split(","):
        cleaned = " ".join(entry.split())
        if cleaned:
            return cleaned
    return "Arial"


def _escape_ass_text(text: str) -> str:
    text = text.replace("\\", "\\\\")
    text = text.replace("{", "\\{").replace("}", "\\}")
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    return text.replace("\n", "\\N")


def _safe_title(title: str) -> str:
    return " ".join(title.replace("\r", " ").replace("\n", " ").split())


def validate_ass_style(
    style: AssStyle,
    *,
    play_res_x: int = 1920,
    play_res_y: int = 1080,
) -> None:
    """Validate every style value before an expensive alignment starts."""
    if not style.font_name.strip():
        raise ValueError("Font name cannot be empty")
    if style.font_size <= 0:
        raise ValueError("Font size must be greater than zero")
    if not 1 <= style.alignment <= 9:
        raise ValueError("ASS alignment must be between 1 and 9")
    if min(style.margin_l, style.margin_r, style.margin_v) < 0:
        raise ValueError("ASS margins cannot be negative")
    if min(style.outline, style.shadow) < 0:
        raise ValueError("ASS outline and shadow cannot be negative")
    if play_res_x <= 0 or play_res_y <= 0:
        raise ValueError("ASS resolution must be positive")
    ass_color(style.primary_color)
    ass_color(style.outline_color)
    ass_color(style.back_color)


def render_ass(
    cues: Sequence[Cue],
    *,
    title: str = "Vilm Lyrics",
    offset_seconds: float = 0.0,
    style: AssStyle | None = None,
    play_res_x: int = 1920,
    play_res_y: int = 1080,
) -> str:
    """Render visible lyric cues as a styled Advanced SubStation Alpha file."""
    style = style or AssStyle()
    validate_ass_style(
        style,
        play_res_x=play_res_x,
        play_res_y=play_res_y,
    )
    font_name = normalize_font_cascade(style.font_name)

    header = _ASS_HEADER.format(
        title=_safe_title(title) or "Vilm Lyrics",
        play_res_x=play_res_x,
        play_res_y=play_res_y,
        font_name=font_name,
        font_size=style.font_size,
        primary_color=ass_color(style.primary_color),
        outline_color=ass_color(style.outline_color),
        back_color=ass_color(style.back_color),
        bold=-1 if style.bold else 0,
        outline=f"{style.outline:g}",
        shadow=f"{style.shadow:g}",
        alignment=style.alignment,
        margin_l=style.margin_l,
        margin_r=style.margin_r,
        margin_v=style.margin_v,
    )
    events = [
        "Dialogue: 0,"
        f"{format_ass_timestamp(cue.start + offset_seconds)},"
        f"{format_ass_timestamp(cue.end + offset_seconds)},"
        f"Vilm,,0,0,0,,{_escape_ass_text(cue.text)}"
        for cue in cues
    ]
    return header + "\n".join(events) + ("\n" if events else "")